-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "frFR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "Élémentaire"
L["rm.era.shaman.elemental.Description"] = "Élémentaire à partir du niveau 10 (la plupart des points en Élémentaire) ; construite d'après Icy Veins et Wowhead. Horion de terre interrompt et achève une cible sur le point de mourir. En mouvement : Horion de flammes, sinon Horion de givre. En solo avec la cible au corps à corps : Horion de terre au-dessus de 30 % de vie, puis la mêlée. Face à trois ennemis ou plus : Totem Nova de feu et Totem de Magma quand vous êtes au corps à corps, et Chaîne d'éclairs. Chaîne d'éclairs sous Maîtrise élémentaire ou Idées claires, sinon Eclair. Rappels : Bouclier de foudre, Arme Croque-roc hors raid, Totem incendiaire ou Totem de Magma, Totem Fontaine de mana ou Totem guérisseur, Maîtrise élémentaire avec Chaîne d'éclairs prête, Rapidité de la nature et Vague de soins sous 30 %, soins après un combat. Les dissipations, les purges et les rangs inférieurs restent à votre charge."
L["rm.era.shaman.elemental.simulator.Name"] = "Élémentaire, Chaîne d'éclairs dès qu'elle est prête (simulateur)"
L["rm.era.shaman.elemental.simulator.Description"] = "La liste Élémentaire de simulateur, une alternative à la rotation intégrée Élémentaire recommandée, désactivée par défaut : activez-la et désactivez l'autre, ou augmentez sa priorité. Chaîne d'éclairs dès qu'elle est prête, même sur une seule cible, Horion de terre tant que Maîtrise élémentaire est active, sinon Eclair. Plus rapide mais bien plus gourmande en mana que la rotation intégrée recommandée ; mêmes interruption, totems et rappels."
L["rm.era.shaman.enhancement.Name"] = "Amélioration"
L["rm.era.shaman.enhancement.Description"] = "Niveaux 1 à 60, y compris sur les royaumes Extrême et en mode autonome, et tout Chaman sans majorité de talents ; construite d'après Icy Veins, Wowhead et simulateur. Eclair engage à distance ; Horion de terre interrompt. En raid, seulement Courroux naturel et Horion de givre (emplacements d'affaiblissement). Face à trois ennemis ou plus qui vous combattent, Totem Nova de feu et Totem de Magma. Puis Courroux naturel, Horion de terre dans l'affaiblissement de Courroux naturel ou pour achever, Horion de flammes quand il ira à son terme, Horion de terre tant qu'il vous reste la moitié de votre mana, et Eclair tant que la cible est hors d'atteinte. Rappels : Arme Croque-roc en solo et Arme Furie-des-vents en donjon, Bouclier de foudre, Totem de Force de la Terre, Totem incendiaire, Totem Furie-des-vents ou Totem de Grâce aérienne, Totem Fontaine de mana ou Totem guérisseur, soins après un combat et en urgence. Totem de Griffes de pierre, Totem de lien terrestre, l'alternance de totems et les améliorations raciales sont listés désactivés ; les dissipations, les purges et les totems de purification restent à votre charge."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "Amélioration, Horion de flammes d'abord (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "L'Amélioration de Warcraft Tavern, une alternative à la rotation intégrée Amélioration recommandée, désactivée par défaut : activez-la et désactivez l'autre, ou augmentez sa priorité. Arme Furie-des-vents dès que vous l'apprenez, Frappe-tempête, Horion de flammes avant tout horion direct, puis Horion de terre tant que votre menace est faible, ou Horion de givre en groupe une fois qu'elle est élevée ; Totem de Magma et Chaîne d'éclairs contre les groupes. Mêmes totems et rappels que la rotation intégrée recommandée."
L["rm.era.shaman.restoration.Name"] = "Restauration"
L["rm.era.shaman.restoration.Description"] = "Restauration à partir du niveau 10 (la plupart des points en Restauration) ; construite d'après Icy Veins et Wowhead. Sur votre cible amicale : Vague de soins sous Rapidité de la nature, Rapidité de la nature sous 30 %, Vague de soins inférieurs sous 40 %, Guérison du poison ou Guérison des maladies, Salve de guérison quand trois membres du groupe proches de vous sont sous 85 %, sinon Vague de soins sous 90 %. Sur un ennemi qu'elle combat : interruption par Horion de terre, Chaîne d'éclairs contre les groupes, Horion de flammes, Eclair à distance, mêlée. Rappels : Bouclier de foudre et Arme Croque-roc en solo, Totem de Vague de mana en groupe, Totem Fontaine de mana, Totem de Force de la Terre, Totem incendiaire. Le choix de qui soigner, les rangs inférieurs et le Totem de Séisme ou les totems de purification restent à votre charge ; maintenir Flots de soins sur le tank est listé désactivé."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "Restauration, Salve de guérison d'abord (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "La Restauration de Warcraft Tavern, une alternative à la rotation intégrée Restauration recommandée, désactivée par défaut : activez-la et désactivez l'autre, ou augmentez sa priorité. Salve de guérison est le soin pour quiconque est sous 90 %, avec Vague de soins inférieurs pour quelqu'un sur le point de mourir ; Vague de soins est réservée à un soigneur de tank assigné avec Flots de soins (listé désactivé). Mêmes guérisons, dégâts sur les ennemis et rappels de totems que la rotation intégrée recommandée."
L["rm.forever.shaman.elemental.Name"] = "Élémentaire"
L["rm.forever.shaman.elemental.Description"] = "Élémentaire à distance dès que Élémentaire est votre arbre de talents principal avec 21 points (palier d'Explosion de lave), d'après Icy Veins (avant cela, la rotation intégrée Amélioration joue l'hybride de mêlée que recommandent tous les guides). Engage avec Eclair (Chaîne d'éclairs contre un groupe), ne lance que des sorts instantanés en mouvement, utilise Nova de feu et Chaîne d'éclairs face à trois ennemis ou plus, maintient Horion de flammes, Explosion de lave dès qu'elle est prête, Frappe-tempête et Horion de terre si vous connaissez Frappe-tempête, Nova de feu sur Idées claires en groupe, puis Eclair. Rappels : bouclier, enchantement d'arme, Totem incendiaire ou Totem de Magma, totems de groupe, Maîtrise élémentaire, interruption. Les points de vie et le mana sont masqués aux addons sur Forever, donc vous soigner et faire une pause pour récupérer du mana est à votre appréciation. À votre charge : le kiting avec Totem de lien terrestre, Horion de givre, Expiation et les autres totems."
L["rm.forever.shaman.enhancement.Name"] = "Amélioration (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "Amélioration au corps à corps du niveau 1 à 60, et la rotation par défaut de tout Chaman avant Explosion de lave ou Totem de Vague de mana. Engage à distance avec Eclair, puis Frappe-tempête dès qu'elle est prête, un Eclair instantané à cinq cumuls d'Arme du Maelström, Nova de feu (avec un totem de feu posé) et Horion de flammes face à trois ennemis ou plus, Horion de terre pendant l'affaiblissement de Frappe-tempête, Horion de flammes en groupe, et Horion de terre dès qu'il est prêt ; Eclair comble le creux tant que la cible est hors d'atteinte. Les points de vie et le mana sont masqués aux addons sur Forever, donc vous soigner et faire une pause pour récupérer du mana est à votre appréciation (la rotation intégrée Wowhead économise le mana à la place). Rappels : enchantement d'arme (Furie-des-vents, sinon Langue de feu, sinon Croque-roc), Bouclier d'eau ou Bouclier de foudre, l'interruption par Horion de terre, Totem incendiaire ou Totem de Magma, totems de groupe, Rage long-voyante, Totem de Griffes de pierre. À votre charge : les préréglages de totems, Horion de givre, Expiation et les autres totems."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "Amélioration, économe en mana (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "L'Amélioration économe en mana de Wowhead et Mobalytics : l'attaque automatique fait le travail, Frappe-tempête seulement quand la régénération de mana de Frappe-tempête améliorée est inactive, pas d'Horion de terre dans la rotation (les horions servent à engager et à interrompre), et en groupe ou contre un groupe d'ennemis, Totem incendiaire avec Nova de feu dès qu'elle est prête. Mêmes rappels d'enchantement d'arme, de bouclier et d'interruption que la rotation intégrée Icy Veins. Choisissez-la plutôt que cette rotation intégrée si vous manquez de mana. Une alternative à la rotation intégrée Amélioration recommandée, désactivée par défaut : activez-la et désactivez l'autre, ou augmentez sa priorité."
L["rm.forever.shaman.restoration.Name"] = "Restauration"
L["rm.forever.shaman.restoration.Description"] = "Soins dès que Restauration est votre arbre de talents principal avec 16 points (palier de Totem de Vague de mana), d'après Icy Veins. Avec une cible amicale : une Vague de soins instantanée une fois Rapidité de la nature utilisée, Guérison du poison et Guérison des maladies, Remous sur une cible qui n'en a pas, Salve de guérison en groupe, Vague de soins. Vous choisissez qui soigner en le ciblant ; les points de vie et le mana sont masqués aux addons sur Forever, donc le moment d'utiliser Rapidité de la nature et Vague de soins inférieurs est à votre appréciation. Avec une cible hostile et personne à soigner : Nova de feu et Chaîne d'éclairs contre les groupes, Frappe-tempête et Horion de terre si vous connaissez Frappe-tempête, Horion de flammes sur les élites et les boss, Eclair, puis la mêlée. Rappels : Bouclier d'eau, l'interruption par Horion de terre, Totem de Vague de mana et les totems d'amélioration de groupe. À votre charge : les rangs inférieurs, les autres totems, Expiation et Loup fantôme."
L["rm.mop.shaman.elemental.Name"] = "Recommandée"
L["rm.mop.shaman.elemental.Description"] = "Recommandée pour Élémentaire à partir du niveau 10, choisie dans la spécialisation Élémentaire. L'ordre de Wowhead : un Eclair pour ouvrir (Explosion de lave avec Fureur libérée), Déchaînement des éléments avec Fureur libérée, Horion de flammes quand il manque ou va expirer sur une cible qui va survivre, Explosion de lave dans Horion de flammes (et sur chaque Vague de lave), Explosion élémentaire, Horion de terre à six charges de Bouclier de foudre tant qu'il reste 6 secondes à Horion de flammes, Chaîne d'éclairs face à deux ennemis, Eclair. Quatre ennemis ou plus sur vous : Totem de magma au corps à corps, Explosions de lave gratuites, Faisceau de lave pendant Ascendance, Chaîne d'éclairs. En mouvement, elle n'affiche que des sorts instantanés. Rappels : Bouclier de foudre, Arme Langue de feu, Totem incendiaire, Totem d'élémentaire de feu sur les élites et les boss, Maîtrise élémentaire, Ascendance après une Explosion de lave, Rapidité ancestrale, Totem fouette-tempête et Furie sanguinaire en groupe, Cisaille de vent, Orage pour le mana, Rage du chaman et Transfert astral quand votre vie est basse. Séisme et Totem d'élémentaire de terre sont listés mais désactivés. À votre charge : Grâce du marcheur des esprits, Horion de flammes sur les cibles supplémentaires et votre placement."
L["rm.mop.shaman.enhancement.Name"] = "Recommandée"
L["rm.mop.shaman.enhancement.Description"] = "Recommandée pour Amélioration à partir du niveau 10, choisie dans la spécialisation Amélioration. L'ordre de Wowhead : Déchaînement des éléments pendant l'approche, puis Déchaînement des éléments avec Fureur libérée, Explosion élémentaire et Eclair à cinq cumuls d'Arme du Maelström (ou intercalés à trois quand votre prochain coup est à plus d'une seconde), Explosion orageuse pendant Ascendance, Frappe-tempête (Frappe primordiale avant le niveau 26), Fouet de lave, Horion de flammes sous Déchaînement de la flamme, Déchaînement des éléments, Horion de terre. Deux ennemis ou plus sur vous : Chaîne d'éclairs au lieu d'Eclair, Fouet de lave pour propager Horion de flammes, Nova de feu à partir de quatre, Totem de magma à partir de six. Rappels : Bouclier de foudre, Arme Furie-des-vents sur la main droite et Arme Langue de feu sur la main gauche, Totem incendiaire, Totem d'élémentaire de feu, Esprit farouche, Ascendance après Frappe-tempête, Maîtrise élémentaire, Rapidité ancestrale, Totem fouette-tempête et Furie sanguinaire en groupe, Cisaille de vent, Rage du chaman et Transfert astral quand votre vie est basse. Totem d'élémentaire de terre est listé mais désactivé."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "Fouet de lave d'abord (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "Désactivée par défaut ; même condition de bascule que la rotation intégrée Amélioration recommandée : activez-la et désactivez l'autre pour l'utiliser. L'ordre d'Icy Veins : Frappe-tempête, puis Fouet de lave avant de dépenser Arme du Maelström, Eclair à cinq cumuls ou dès trois quand il arrive avant votre prochain coup, Déchaînement des éléments puis Horion de flammes, Horion de terre. Face à quatre ennemis ou plus, elle propage Horion de flammes avec Fouet de lave et utilise Nova de feu ; Chaîne d'éclairs remplace Eclair contre les groupes. Rage du chaman est suggérée dès qu'elle est prête en combat ; autres rappels identiques à la rotation intégrée recommandée."
L["rm.mop.shaman.enhancement.simulator.Name"] = "Intercaler chaque cumul (simulateur)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "Désactivée par défaut ; même condition de bascule que la rotation intégrée Amélioration recommandée : activez-la et désactivez l'autre pour l'utiliser. La liste du simulateur pour les joueurs qui placent leurs incantations entre les coups : Eclair, Explosion élémentaire ou Chaîne d'éclairs avec n'importe quel nombre de cumuls d'Arme du Maelström dès que l'incantation se termine avant votre prochain coup de la main droite, Déchaînement des éléments aussi dès que Horion de flammes manque, et Horion de terre seulement sous deux cumuls. Rappels identiques à la rotation intégrée recommandée."
L["rm.mop.shaman.restoration.Name"] = "Recommandée"
L["rm.mop.shaman.restoration.Description"] = "Recommandée pour Restauration à partir du niveau 10, choisie dans la spécialisation Restauration. Soigne votre cible amicale (Rotation Master ne peut pas choisir qui soigner) : Vague de soins supérieurs sous Rapidité ancestrale, Afflux de soins sous 35 %, Purifier l'esprit sur la magie ou les malédictions, Déchaînement des éléments puis Pluie guérisseuse quand trois alliés proches sont blessés, Remous, Salve de guérison pour les dégâts de groupe, Vague de soins supérieurs sous 60 %, Vague de soins sous 90 %. Avec une cible attaquable, elle inflige des dégâts à la place (Horion de flammes, Explosion de lave, Explosion élémentaire, Eclair). Rappels : Bouclier d’eau, Arme Viveterre, Bouclier de terre sur votre focalisation, Totem guérisseur quand quelqu'un est blessé, Totem de vague de mana, Totem de marée de soins contre les gros dégâts de groupe, Maîtrise élémentaire ou Soutien ancestral, Rapidité ancestrale sur une cible basse, Grâce du marcheur des esprits en mouvement, Furie sanguinaire, Cisaille de vent. Ascendance et Totem de lien d'esprit sont listés mais désactivés : utilisez-les quand votre raid vous les attribue."
L["rm.mop.shaman.restoration.hekili.Name"] = "Paliers de vie (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "Désactivée par défaut ; même condition de bascule que la rotation intégrée Restauration recommandée : activez-la et désactivez l'autre pour l'utiliser. La liste de Hekili maintient Bouclier de terre et Remous sur votre cible, et Totem guérisseur et Pluie guérisseuse dès qu'ils sont inactifs, puis soigne selon la vie moyenne de votre groupe à moins de 40 mètres : Salve de guérison sous 80 %, Vague de soins sur une cible sous 70 %, Vague de soins supérieurs sous 60 %, Afflux de soins sous 40 %, avec Totem de marée de soins, Soutien ancestral et Totem de vague de mana sur les mêmes paliers. Une cible attaquable reçoit des dégâts plus Horion de terre."
L["rm.mop.shaman.unspecialized.Name"] = "Sans spécialisation"
L["rm.mop.shaman.unspecialized.Description"] = "Pour les niveaux 1 à 9, et tout Chaman qui n'a pas encore choisi de spécialisation ; chaque rotation intégrée de spécialisation prend le relais dès que vous en choisissez une. Eclair pour engager à distance, Afflux de soins quand votre vie est basse et que vous êtes seul, Frappe primordiale, Horion de terre, et Eclair hors de portée de mêlée. Maintient Bouclier de foudre."
L["rm.retail.shaman.elemental.Name"] = "Assistant de combat Blizzard"
L["rm.retail.shaman.elemental.Description"] = "Recommandée pour Élémentaire dans Midnight. En combat, le jeu masque désormais Horion de flammes, vos améliorations, le Maelström, les temps de recharge et la vie aux addons ; elle affiche donc la suggestion de l'Assistant de combat de Blizzard lui-même (la rotation à un bouton), et s'arrête pendant que vous incantez ou quand aucun ennemi n'est ciblé. Rappels pour ce qu'elle laisse de côté : Ascendance, Élémentaire de feu ou Élémentaire de tempête et Rapidité de la nature en combat, Grâce du marcheur des esprits en mouvement, Bouclier de foudre et Fureur-du-ciel entre les combats (la suggestion de Blizzard entretient vos enchantements d'arme et de bouclier), Cisaille de vent sur une incantation interruptible (elle ne s'allume que là où le jeu permet de lire l'incantation), Transfert astral dès qu'il est prêt en combat (la vie est masquée sur Retail, donc le moment de l'utiliser est à votre appréciation)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "Référence (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "Référence uniquement, désactivée par défaut : l'ordre d'Icy Veins et de SimulationCraft lit Horion de flammes, Maître des éléments et Gardien des tempêtes, que Midnight masque en combat ; le Maelström est masqué sur Retail, donc les dépenseurs se lancent à leur coût plutôt que près du maximum de Maelström. Gardien des tempêtes et Explosion de lave avant l'engagement. Face à trois ennemis engagés ou plus : Gardien des tempêtes, Rapidité ancestrale, Horion de flammes, Chaîne d’éclairs avec Gardien des tempêtes, Explosion élémentaire, Séisme, Explosion de lave sur Vague de lave, Tempête, Chaîne d’éclairs. Sinon Gardien des tempêtes, Rapidité ancestrale, Horion de flammes et Brasier voltaïque dans leurs derniers 30 % hors de Maître des éléments, Explosion de lave pour le déclencher, Tempête et l'Éclair de Gardien des tempêtes pendant celui-ci, Explosion élémentaire ou Horion de terre pendant celui-ci, Brasier voltaïque, Tempête, Horion de flammes ou Horion de givre en mouvement, Explosion élémentaire ou Horion de terre dès que vous pouvez vous le permettre, Éclair. Rappels : Ascendance une fois Gardien des tempêtes utilisé, les élémentaires, Grâce du marcheur des esprits, et les rappels communs."
L["rm.retail.shaman.enhancement.Name"] = "Assistant de combat Blizzard"
L["rm.retail.shaman.enhancement.Description"] = "Recommandée pour Amélioration dans Midnight. Affiche la suggestion de l'Assistant de combat de Blizzard (elle dépense Arme du Maelström, maintient Horion de flammes et gère Totem déferlant et Fracture), et s'arrête pendant que vous incantez ou quand aucun ennemi n'est ciblé. Rappels pour ce qu'elle laisse de côté : Ascendance, Vents funestes et Esprit farouche en combat, Bouclier de foudre et Fureur-du-ciel entre les combats (la suggestion de Blizzard entretient Arme Furie-des-vents), Cisaille de vent, Transfert astral."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "Porte-tempête, référence (SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "Référence uniquement, désactivée par défaut : la liste Porte-tempête de SimulationCraft (Icy Veins et Wowhead concordent) lit Horion de flammes, Impact foudroyant, Flammes flagellantes et les temps de recharge, que Midnight masque en combat. Face à trois ennemis engagés ou plus : Impact foudroyant pour son amélioration, Tempête à 10 cumuls d'Arme du Maelström, Chaîne d’éclairs à 9, Impact foudroyant, Fouet de lave, Fracture. Puis Tempête primordiale à 9, Brasier voltaïque ou Horion de flammes quand Horion de flammes manque, Fracture, Impact foudroyant pour son amélioration, Fouet de lave pour Flammes flagellantes, Frappevent, Tempête ou Éclair à 10 (8 avec Brasier voltaïque ou Impact foudroyant presque prêt), Frappe-tempête à deux charges, Fouet de lave, Frappe-tempête, Brasier voltaïque, Impact foudroyant, Éclair à 5, Horion de flammes. Rappels : Vents funestes, Ascendance hors de Vents funestes, Esprit farouche, et les rappels communs."
L["rm.retail.shaman.enhancement.totemic.Name"] = "Totémique, référence (SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "Référence uniquement, désactivée par défaut : la liste Totémique de SimulationCraft lit Horion de flammes, Main brûlante, Feu tourbillonnant, Impact foudroyant et Vents funestes, que Midnight masque en combat. Face à trois ennemis engagés ou plus : Impact foudroyant, Chaîne d’éclairs à 5 cumuls d'Arme du Maelström. Puis Brasier voltaïque ou Horion de flammes quand Horion de flammes manque, Totem déferlant, Fracture, Fouet de lave avec Main brûlante ou Feu tourbillonnant, Impact foudroyant pour son amélioration, Tempête primordiale à 10, Frappevent, Impact foudroyant et Frappe-tempête pendant Vents funestes, Éclair à 5, Impact foudroyant, Fouet de lave, Frappe-tempête, Brasier voltaïque, Horion de flammes. Mêmes rappels que la référence Porte-tempête."
L["rm.retail.shaman.initial.Name"] = "Assistant de combat Blizzard"
L["rm.retail.shaman.initial.Description"] = "Recommandée avant de choisir une spécialisation (tant que le jeu signale la spécialisation initiale du Chaman). Met en surbrillance le prochain sort suggéré par l'Assistant de combat de Blizzard, le seul conseil de rotation que le jeu laisse encore lire à un addon en combat dans Midnight ; elle attend pendant que vous incantez ou canalisez. En complément, les rappels que partagent toutes les rotations intégrées du Chaman, chacun dès que vous connaissez son sort. Lorsque vous choisissez une spécialisation au niveau 10, les rotations intégrées de cette spécialisation prennent le relais."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "Restauration dans Midnight, pour référence : l'Assistant de combat de Blizzard ne couvre pas les soigneurs, le jeu masque la vie de tout le monde en combat et Rotation Master choisit un sort, pas une cible ; elle classe donc vos outils de soin selon leur disponibilité sur ce que vous ciblez, et vous laisse décider qui soigner. Sur une cible amicale : Totem guérisseur, Déchaînement de la vie, Pluie guérisseuse en groupe, Totem déferlant, Remous, Salve de guérison en groupe, Vague de soins. Sur un ennemi : Horion de flammes quand il manque, Explosion de lave, Éclair. Rappels : Bouclier d’eau, Bouclier de terre sur une cible amicale et Fureur-du-ciel entre les combats ; Rapidité de la nature en combat ; Totem de marée de soins et Totem de lien d'esprit en combat de groupe ; Cisaille de vent ; Transfert astral."
L["rm.sod.shaman.elemental.Name"] = "Élémentaire (SoD)"
L["rm.sod.shaman.elemental.Description"] = "Élémentaire de la Saison de découverte à partir du niveau 10 (la plupart des points en Élémentaire) ; construite d'après la phase 6 de simulateur, Wowhead et Icy Veins. Horion de terre interrompt. En mouvement : Horion de flammes, Horion de terre à huit charges de Bouclier de foudre, Explosion de lave ou Chaîne d'éclairs sur un proc de Vague de puissance. Face à trois ennemis ou plus : Horion de flammes, Chaîne d'éclairs, Nova de feu, Explosion de lave, Horion de terre à huit charges, Totem de Magma. Puis Explosion de lave sur Vague de puissance, Horion de flammes maintenu, Explosion de lave tant que votre Horion de flammes dure, Horion de terre à huit charges, Chaîne d'éclairs face à deux ennemis, Eclair. Rappels : Arme Langue de feu pour Brûlure, Bouclier de foudre, Bouclier de terre sur vous-même, Esprit de l’alpha, Esprit farouche, Rage du chaman, Maîtrise élémentaire, totems. Les bijoux, Projection totémique, les dissipations et les purges restent à votre charge."
L["rm.sod.shaman.enhancement.Name"] = "Amélioration (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "Saison de découverte, niveaux 1 à 60 avec les runes à mesure que vous les gravez, deux armes ou arme à deux mains, et tout Chaman de la Saison de découverte auquel aucune autre rotation intégrée ne convient ; construite d'après la phase 6 de simulateur, Icy Veins et Wowhead. Horion de flammes engage ; Horion de terre interrompt. Face à trois ennemis ou plus : Magma, Nova de feu depuis un totem de feu, Chaîne d'éclairs à quatre cumuls de Maelström, Horion de flammes. Puis Explosion de lave à cinq cumuls de Maelström, Frappe-tempête, Fouet de lave, Eclair à cinq cumuls, Horion de flammes quand il ira à son terme, Horion de terre, Éclair de lave, Eclair à distance. Rappels : Arme Furie-des-vents (Arme Croque-roc avant), Arme Langue de feu sur la main gauche avec Fouet de lave (sinon Furie-des-vents ; jamais sur un bouclier ; une ligne Icy Veins avec Furie-des-vents sur les deux armes est listée désactivée), Bouclier d'eau ou Bouclier de foudre, Esprit de l’alpha, Esprit farouche, Rage du chaman sous 65 % de mana, totems, Soutien ancestral. Projection totémique, les dissipations et les purges restent à votre charge."
L["rm.sod.shaman.restoration.Name"] = "Restauration (SoD)"
L["rm.sod.shaman.restoration.Description"] = "Restauration de la Saison de découverte à partir du niveau 10 (la plupart des points en Restauration) ; construite d'après Icy Veins et Wowhead. Sur votre cible amicale : Remous puis Vague de soins inférieurs sous 40 %, Guérison du poison ou Guérison des maladies, Pluie guérisseuse quand trois membres du groupe proches de vous sont sous 85 %, Salve de guérison quand deux le sont (immédiatement sur un proc de Vague de puissance), Remous sous 95 % pour Raz-de-marée, Vague de soins sous 90 %. Sur un ennemi, elle combat. Rappels : Bouclier d’eau (Bouclier de foudre avant), Bouclier de terre sur votre cible amicale ou sur vous-même, Rage du chaman, Totem de Vague de mana, Totem Fontaine de mana et Totem de Force de la Terre. Le choix de qui soigner et le Totem de Séisme ou les totems de purification restent à votre charge."
L["rm.sod.shaman.tank.Name"] = "Tank (SoD, Voie de la terre)"
L["rm.sod.shaman.tank.Description"] = "Tank de la Saison de découverte, choisie dès que Voie de la terre est gravée ; construite d'après Icy Veins, Wowhead, simulateur et Warcraft Tavern. Horion de flammes engage. Horion de terre provoque une cible au corps à corps qui ne vous attaque pas, et interrompt. Face à deux ennemis ou plus : Éclair de lave, Horion de flammes, Chaîne d'éclairs à cinq cumuls de Maelström ou sur Vague de puissance, Nova de feu à cinq cumuls. Puis Horion de flammes maintenu, Explosion de lave sur Vague de puissance ou tant que Horion de flammes dure, Frappe-tempête, Horion de terre, Eclair à cinq cumuls, Éclair de lave, Horion de givre. Rappels : Croque-roc, Bouclier de foudre, Esprit de l’alpha sur vous-même, Esprit farouche, Rage du chaman, Totem incendiaire ou Totem de Magma, et les totems de groupe."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "Élémentaire (Icy Veins & simulateur)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "Élémentaire lanceur de sorts pour l'arbre de talents Élémentaire. Eclair sert de sort de remplissage ; Chaîne d'éclairs part avec Maîtrise élémentaire, sur Idées claires tant qu'il vous reste 40 % de mana, ou librement au-dessus de 80 % ; Horion de flammes seulement en mouvement ; Horion de terre pour interrompre ; Nova de feu, Chaîne d'éclairs et Totem de Magma contre les groupes d'ennemis. Avant Chaîne d'éclairs, une cible au corps à corps est laissée à l'attaque automatique pour économiser le mana. Rappels : Bouclier d'eau ou Bouclier de foudre, un enchantement d'arme, Totem de courroux (ou Totem incendiaire sur les combats longs), Totem de courroux de l'air, Totem Fontaine de mana, Appel totémique après le combat, Maîtrise élémentaire et Furie sanguinaire/Héroïsme."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "Élémentaire (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "L'Élémentaire de NextActionTBC, une alternative à la rotation intégrée Élémentaire d'Icy Veins recommandée, désactivée par défaut : activez-la et désactivez l'autre, ou augmentez sa priorité. Maintient Horion de flammes sur la cible, Chaîne d'éclairs seulement contre deux ennemis ou plus tant que vous avez plus de 30 % de mana, Eclair sinon. Vous rappelle Bouclier de foudre, un enchantement d'arme, Maîtrise élémentaire et Furie sanguinaire/Héroïsme ; les totems restent manuels."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "Élémentaire (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "L'Élémentaire de Wowhead, une alternative à la rotation intégrée Élémentaire d'Icy Veins recommandée, désactivée par défaut : activez-la et désactivez l'autre, ou augmentez sa priorité. Au niveau 70, Chaîne d'éclairs dès qu'elle est prête avec des Eclairs entre deux (pendant la progression, seulement avec Maîtrise élémentaire ou Idées claires), Horion de flammes seulement en mouvement, Horion de terre pour achever une cible qui mourrait avant la fin d'une incantation. Mêmes rappels de totems, de bouclier et de temps de recharge que la variante Icy Veins."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "Amélioration (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "Amélioration au corps à corps du niveau 1 à 70, et la rotation par défaut de tout Chaman auquel aucune autre rotation intégrée ne convient. Engage à distance avec Eclair, interrompt avec Horion de terre, pose les totems Nova de feu et de Magma face à trois ennemis proches ou plus, puis Frappe-tempête, Horion de terre tant que l'affaiblissement de Frappe-tempête est actif, Horion de flammes sur une cible qui va survivre, Horion de terre dès qu'il est prêt, et Eclair tant que la cible est hors d'atteinte. Rappels séparés : enchantements d'arme, Bouclier d'eau ou Bouclier de foudre, Totem de Force de la Terre, Totem Furie-des-vents (en groupe) ou Totem de Grâce aérienne (en solo), Totem incendiaire sur les combats longs, totems d'eau, Rage du chaman, Furie sanguinaire/Héroïsme sur les boss, Totem de Griffes de pierre et Totem d'élémentaire de terre en solo. Le Totem d'élémentaire de feu est une étape facultative, désactivée au départ. Le placement des totems, Loup fantôme et les soins restent à votre charge."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "Amélioration (Wowhead & simulateur)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "Le modèle de raid au niveau 70 pour l'alternance de totems, une alternative à la rotation intégrée Amélioration d'Icy Veins recommandée, désactivée par défaut : activez-la et désactivez l'autre, ou augmentez sa priorité. Frappe-tempête, Totem Nova de feu intercalé, Horion de flammes dès qu'il a expiré, et Horion de terre comme horion principal, Eclair seulement hors d'atteinte. Les rappels alternent Totem Furie-des-vents et Totem de Grâce aérienne, maintiennent le Totem incendiaire, utilisent Rage du chaman quand le mana baisse, et reprennent l'entretien des enchantements d'arme, boucliers et totems de la variante Icy Veins."
L["rm.tbc.shaman.restoration.Name"] = "Restauration"
L["rm.tbc.shaman.restoration.Description"] = "Soins pour l'arbre de talents Restauration, sur votre cible amicale (ou sur vous-même sans cible) : Rapidité de la nature et Vague de soins ou Vague de soins inférieurs en urgence, Guérison du poison et Guérison des maladies, Bouclier de terre sur votre focalisation, Salve de guérison quand trois alliés proches sont blessés, Vague de soins sinon. Avec une cible hostile, passe à Horion de flammes et Eclair pour jouer en solo. Rappels : Bouclier d'eau, Bouclier de terre sur votre focalisation (définissez le tank comme focalisation), Totem de Vague de mana, Totem Fontaine de mana et Totem de Force de la Terre en groupe, Furie sanguinaire/Héroïsme. Le choix de qui soigner et du rang à utiliser vous revient."
